    #[test]
    fn clipped_compositing_keeps_original_texture_coordinates() {
        let full = Bounds {
            origin: point(px(-20.0), px(10.0)),
            size: size(px(100.0), px(50.0)),
        };
        let visible = Bounds {
            origin: point(px(0.0), px(20.0)),
            size: size(px(80.0), px(30.0)),
